        final String expected1 = baseString + "[staticString=staticString,staticInt=12345]";
        final String actual1 = ReflectionToStringBuilder.toString(instance1, null, false, true, SimpleReflectionStaticFieldsFixture.class);
        assertEquals(normalizeToString(expected1), normalizeToString(actual1));

        final String expected2 = baseString + "[staticString=staticString,staticInt=12345]";
        final String actual2 = ReflectionToStringBuilder.toString(instance1, null, true, true, SimpleReflectionStaticFieldsFixture.class);
        assertEquals(normalizeToString(expected2), normalizeToString(actual2));

