    public void testPerson() {
        final Person p = new Person();
        p.name = "John Doe";
        p.age = 33;
        p.smoker = false;
        p.job = new Job();
        p.job.title = "Manager";
        final String pBaseStr = p.getClass().getName() + "@" + Integer.toHexString(System.identityHashCode(p));
        final String pJobStr  = p.job.getClass().getName() + "@" + Integer.toHexString(System.identityHashCode(p.job));

        // Build expected field entries as a set for order-insensitive comparison
        final String expectedJobPart = pJobStr + "[title=Manager]";
        final java.util.Set<String> expectedFields = new java.util.HashSet<>();
        expectedFields.add("name=John Doe");
        expectedFields.add("age=33");
        expectedFields.add("smoker=false");
        expectedFields.add("job=" + expectedJobPart);

        final String actual = new ReflectionToStringBuilder(p, new RecursiveToStringStyle()).toString();

        // Parse actual result: extract prefix and fields
        final int bracketIdx = actual.indexOf('[');
        assertEquals(pBaseStr, actual.substring(0, bracketIdx), "Object prefix mismatch");

        // Extract content between outer brackets
        final String content = actual.substring(bracketIdx + 1, actual.length() - 1);

        // Parse fields, handling nested job object
        final java.util.Set<String> actualFields = new java.util.HashSet<>();
        int depth = 0;
        int start = 0;
        for (int i = 0; i < content.length(); i++) {
            char c = content.charAt(i);
            if (c == '[') {
                depth++;
            } else if (c == ']') {
                depth--;
            } else if (c == ',' && depth == 0) {
                actualFields.add(content.substring(start, i));
                start = i + 1;
            }
        }
        // Add last field
        actualFields.add(content.substring(start));

        assertEquals(expectedFields, actualFields, "Fields mismatch");
    }

