    public void testReflectionHashCodeExcludeFields() {
        final TestObjectWithMultipleFields x = new TestObjectWithMultipleFields(1, 2, 3);

        // Get actual field order to compute expected values correctly
        final java.lang.reflect.Field[] fields = TestObjectWithMultipleFields.class.getDeclaredFields();
        final java.util.Map<String, Integer> fieldValues = new java.util.HashMap<>();
        for (final java.lang.reflect.Field field : fields) {
            field.setAccessible(true);
            try {
                fieldValues.put(field.getName(), (Integer) field.get(x));
            } catch (final IllegalAccessException e) {
                throw new RuntimeException(e);
            }
        }

        // Compute expected full hash by iterating fields in actual order
        int expectedFullHash = 17;
        for (final java.lang.reflect.Field field : fields) {
            expectedFullHash = expectedFullHash * 37 + fieldValues.get(field.getName());
        }

        // Verify full hash code
        assertEquals(expectedFullHash, HashCodeBuilder.reflectionHashCode(x));
        assertEquals(expectedFullHash, HashCodeBuilder.reflectionHashCode(x, (String[]) null));
        assertEquals(expectedFullHash, HashCodeBuilder.reflectionHashCode(x, "xxx"));

        // Test excluding "two": compute expected by iterating all fields except "two"
        int expectedWithoutTwo = 17;
        for (final java.lang.reflect.Field field : fields) {
            if (!"two".equals(field.getName())) {
                expectedWithoutTwo = expectedWithoutTwo * 37 + fieldValues.get(field.getName());
            }
        }
