        int expectedWithoutThree = 17;
        for (final java.lang.reflect.Field field : fields) {
            if (!"three".equals(field.getName())) {
                expectedWithoutThree = expectedWithoutThree * 37 + fieldValues.get(field.getName());
            }
        }
        assertEquals(expectedWithoutThree, HashCodeBuilder.reflectionHashCode(x, "three"));

        // Test excluding "two" and "three"
        int expectedWithoutTwoThree = 17;
        for (final java.lang.reflect.Field field : fields) {
            if (!"two".equals(field.getName()) && !"three".equals(field.getName())) {
                expectedWithoutTwoThree = expectedWithoutTwoThree * 37 + fieldValues.get(field.getName());
            }
        }
        assertEquals(expectedWithoutTwoThree, HashCodeBuilder.reflectionHashCode(x, "two", "three"));

        // Test excluding all fields
        assertEquals(17, HashCodeBuilder.reflectionHashCode(x, "one", "two", "three"));
        assertEquals(17, HashCodeBuilder.reflectionHashCode(x, "one", "two", "three", "xxx"));
    }

