        assertTrue(result4.endsWith("]"));
        String content4 = result4.substring(baseStr4.length() + 1, result4.length() - 1);
        Map<String, String> fields4 = parseFields(content4);
        assertEquals(4, fields4.size());
        assertEquals("staticString", fields4.get("staticString"));
        assertEquals("12345", fields4.get("staticInt"));
        assertEquals("instanceString", fields4.get("instanceString"));
        assertEquals("67890", fields4.get("instanceInt"));
    }

    private Map<String, String> parseFields(String content) {
        Map<String, String> result = new java.util.HashMap<>();
        if (content.isEmpty()) {
            return result;
        }
        // Split by comma, but need to handle potential nested structures
        // Simple approach: split by comma that is followed by a field name (no equals in the value)
        java.util.List<String> pairs = new java.util.ArrayList<>();
        int depth = 0;
        int start = 0;
        for (int i = 0; i < content.length(); i++) {
            char c = content.charAt(i);
            if (c == '[' || c == '{' || c == '(') {
                depth++;
            } else if (c == ']' || c == '}' || c == ')') {
                depth--;
            } else if (c == ',' && depth == 0) {
                pairs.add(content.substring(start, i));
                start = i + 1;
            }
        }
        pairs.add(content.substring(start));

        for (String pair : pairs) {
            int eqIdx = pair.indexOf('=');
            if (eqIdx > 0) {
                String key = pair.substring(0, eqIdx);
                String value = pair.substring(eqIdx + 1);
                result.put(key, value);
            }
        }
        return result;
    }

